def extend_diagonals(grid):
    """Extend every maximal straight diagonal run (>=2 same non-bg cells) in both directions to the grid edge, stopping at other non-bg cells."""
    h,w=len(grid),len(grid[0])
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    out=[r[:] for r in grid]
    starts=[]
    for dr,dc in ((1,1),(1,-1)):
        for i in range(h):
            j = 0 if dc==1 else w-1
            if 0<=i<h and 0<=j<w: starts.append((dr,dc,i,j))
        for j in range(1,w) if dc==1 else range(w-1):
            starts.append((dr,dc,0,j))
    for dr,dc,r,c in starts:
        cells=[]
        while 0<=r<h and 0<=c<w:
            if grid[r][c]!=bg: cells.append((r,c,grid[r][c]))
            r+=dr; c+=dc
        groups=[];cur=[]
        for cell in cells:
            if cur and cell[2]==cur[-1][2] and cell[0]==cur[-1][0]+dr and cell[1]==cur[-1][1]+dc:
                cur.append(cell)
            else:
                if cur: groups.append(cur)
                cur=[cell]
        if cur: groups.append(cur)
        for g in groups:
            if len(g)<2: continue
            col=g[0][2]
            for end,sgn in ((g[0],-1),(g[-1],1)):
                r0,c0=end[0],end[1]
                r,c=r0+sgn*dr, c0+sgn*dc
                while 0<=r<h and 0<=c<w and out[r][c]==bg:
                    out[r][c]=col; r+=sgn*dr; c+=sgn*dc
    return out

